{
  "passageId": "virtual-identity-defamation",
  "items": [
    {
      "id": "R1",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "자기표현이 두 연기로 이루어진다는 설명을 각 연기의 의미를 밝혀 구체화한다."
    },
    {
      "id": "R2",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "연기에서 집중하는 요소를 기준으로 표면 연기의 외적 형식과 심층 연기의 내면 정서를 대비한다."
    },
    {
      "id": "R3",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "사회적 자기표현 일반에서 가상 공간의 자기표현으로 논의 영역을 옮긴다."
    },
    {
      "id": "R4",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "가상 공간의 활발한 자기표현에서 자기 정체성의 다양한 발현으로 화제를 이어 간다."
    },
    {
      "id": "R5",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "가상 공간에서 다양하게 나타난다고 설명하는 자기 정체성이라는 용어의 뜻을 밝힌다."
    },
    {
      "id": "R6",
      "type": "CAUSE",
      "otherName": "",
      "reason": "익명성이 현실에서 위축된 사람의 적극적인 자기표현을 실제로 가능하게 하는 작용을 설명한다."
    },
    {
      "id": "R7",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "적극적인 자기표현과 다른 인격체로의 활동을 가상 공간에서 나타나는 같은 층위의 양상으로 나란히 제시한다."
    },
    {
      "id": "R8",
      "type": "PARALLEL",
      "otherName": "",
      "reason": "다른 인격체로 활동하는 것과 억압된 정서를 공격적으로 표출하는 것을 병렬적으로 제시한다."
    },
    {
      "id": "R9",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "적극적 자기표현과 다른 인격체로의 활동 등은 자기 정체성이 다양하게 나타난다는 설명의 구체적 양상이다."
    },
    {
      "id": "R10",
      "type": "CAUSE",
      "otherName": "",
      "reason": "현실의 정체성을 감추는 활동 양상을 인터넷 ID에 대한 사이버 폭력의 발생과 연결되는 요인으로 제시한다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "억압된 정서의 공격적 표출을 인터넷 ID에 대한 사이버 폭력으로 이어지는 요인으로 설명한다."
    },
    {
      "id": "R12",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "사이버 폭력의 대상으로 언급된 인터넷 ID가 무엇을 뜻하는지 사례를 포함해 풀이한다."
    },
    {
      "id": "R13",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "인터넷 ID에 대한 사이버 폭력 현상에서 그러한 공격의 법적 책임을 둘러싼 논란으로 논의를 옮긴다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "법적 책임 논란의 핵심 쟁점이 인터넷 ID의 명예 주체성 인정 여부임을 밝혀 구체화한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자기 정체성이 현실과 가상에 걸친 복합적인 것이라는 설명이 인터넷 정체성도 개인 정체성의 일부라는 판단을 뒷받침한다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인터넷 정체성이 개인 정체성의 일부라는 점을 근거로 인터넷 ID의 명예도 보호해야 한다는 당위를 도출한다."
    },
    {
      "id": "R17",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자유로운 생성·변경·소멸과 복수 개설 가능성을 인터넷 ID가 사용자 구별 장치에 불과하다는 판단의 근거로 삼는다."
    },
    {
      "id": "R18",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인터넷 ID를 사용자 개인과 동일시할 수 없다는 점이 명예 주체성을 부정하는 결론을 뒷받침한다."
    },
    {
      "id": "R19",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인터넷 ID 자체는 사람이 아니라는 점에서 명예 주체성을 인정할 수 없다는 결론을 도출한다."
    },
    {
      "id": "R20",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인터넷 ID의 명예 주체성을 인정하는 입장과 부정하는 입장의 상반된 견해를 나란히 제시한다."
    },
    {
      "id": "R21",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "헌법재판소가 대법원의 법적 책임 판단 기준을 수용했음을 명시한다."
    },
    {
      "id": "R22",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "헌법재판소가 내린 결정의 구체적 내용으로 다수 의견을 제시한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "헌법재판소의 해당 결정에서 제시된 소수 의견의 구체적 내용을 설명한다."
    },
    {
      "id": "R24",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "대법원의 제3자 식별 가능성 기준을 인터넷 ID 관련 사건의 책임 판단에 적용한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "피해자가 특정되지 않는다는 판단을 근거로 가해자의 법적 책임이 성립하지 않는다는 결론을 도출한다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인터넷 ID가 성명과 같은 기능을 한다는 점으로 제3자의 인식 여부를 책임의 근거로 삼을 수 없다는 판단을 뒷받침한다."
    },
    {
      "id": "R27",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "제3자의 사용자 식별 여부를 책임 판단 기준으로 삼는 다수 의견과 이를 인정하지 않는 소수 의견을 대비한다."
    },
    {
      "id": "R28",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "인터넷 ID의 명예 주체성을 둘러싼 일반적 논쟁에서 대법원과 헌법재판소의 구체적인 사법 판단으로 논의를 옮긴다."
    },
    {
      "id": "R29",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "인터넷 ID를 현실의 성명과 구별하는 부정론과 가상 공간에서 성명과 같은 기능을 한다고 보는 소수 의견을 대비한다."
    }
  ]
}

